//! Literal Rust translation of `c_src/test.c`.
//!
//! All output goes through the platform C library's `printf` so that the
//! generated bytes and the stdio buffering behaviour match the C original
//! exactly.

use core::ffi::{c_char, c_int, c_void};
use core::ptr;

use crate::cjson::*;
use crate::cshim::*;

macro_rules! cs {
    ($s:expr) => {
        $s.as_ptr() as *const c_char
    };
}

/// Used by some code below as an example datatype.
#[repr(C)]
pub struct record {
    pub precision: *const c_char,
    pub lat: f64,
    pub lon: f64,
    pub address: *const c_char,
    pub city: *const c_char,
    pub state: *const c_char,
    pub zip: *const c_char,
    pub country: *const c_char,
}

/// Create a bunch of objects as demonstration.
unsafe fn print_preallocated(root: *mut cJSON) -> c_int {
    /* declarations */
    let out: *mut c_char;
    let buf: *mut c_char;
    let buf_fail: *mut c_char;
    let len: usize;
    let len_fail: usize;

    /* formatted print */
    out = cJSON_Print(root);

    /* create buffer to succeed */
    /* the extra 5 bytes are because of inaccuracies when reserving memory */
    len = strlen(out) + 5;
    buf = malloc(len) as *mut c_char;
    if buf.is_null() {
        printf(cs!(b"Failed to allocate memory.\n\0"));
        exit(1);
    }

    /* create buffer to fail */
    len_fail = strlen(out);
    buf_fail = malloc(len_fail) as *mut c_char;
    if buf_fail.is_null() {
        printf(cs!(b"Failed to allocate memory.\n\0"));
        exit(1);
    }

    /* Print to buffer */
    if cJSON_PrintPreallocated(root, buf, len as c_int, 1) == 0 {
        printf(cs!(b"cJSON_PrintPreallocated failed!\n\0"));
        if strcmp(out, buf) != 0 {
            printf(cs!(b"cJSON_PrintPreallocated not the same as cJSON_Print!\n\0"));
            printf(cs!(b"cJSON_Print result:\n%s\n\0"), out);
            printf(cs!(b"cJSON_PrintPreallocated result:\n%s\n\0"), buf);
        }
        free(out as *mut c_void);
        free(buf_fail as *mut c_void);
        free(buf as *mut c_void);
        return -1;
    }

    /* success */
    printf(cs!(b"%s\n\0"), buf);

    /* force it to fail */
    if cJSON_PrintPreallocated(root, buf_fail, len_fail as c_int, 1) != 0 {
        printf(cs!(
            b"cJSON_PrintPreallocated failed to show error with insufficient memory!\n\0"
        ));
        printf(cs!(b"cJSON_Print result:\n%s\n\0"), out);
        printf(cs!(b"cJSON_PrintPreallocated result:\n%s\n\0"), buf_fail);
        free(out as *mut c_void);
        free(buf_fail as *mut c_void);
        free(buf as *mut c_void);
        return -1;
    }

    free(out as *mut c_void);
    free(buf_fail as *mut c_void);
    free(buf as *mut c_void);
    0
}

/// Create a bunch of objects as demonstration.
unsafe fn create_objects(
    strings: *const *const c_char,
    numbers: *const [c_int; 3],
    ids: *const c_int,
    fields: *const record,
) {
    /* declare a few. */
    let mut root: *mut cJSON;
    let fmt: *mut cJSON;
    let img: *mut cJSON;
    let thm: *mut cJSON;
    let mut fld: *mut cJSON;
    let mut i: c_int;

    let zero: f64 = 0.0;

    /* Here we construct some JSON standards, from the JSON site. */

    /* Our "Video" datatype: */
    root = cJSON_CreateObject();
    cJSON_AddItemToObject(
        root,
        cs!(b"name\0"),
        cJSON_CreateString(cs!(b"Jack (\"Bee\") Nimble\0")),
    );
    fmt = cJSON_CreateObject();
    cJSON_AddItemToObject(root, cs!(b"format\0"), fmt);
    cJSON_AddStringToObject(fmt, cs!(b"type\0"), cs!(b"rect\0"));
    cJSON_AddNumberToObject(fmt, cs!(b"width\0"), 1920.0);
    cJSON_AddNumberToObject(fmt, cs!(b"height\0"), 1080.0);
    cJSON_AddFalseToObject(fmt, cs!(b"interlace\0"));
    cJSON_AddNumberToObject(fmt, cs!(b"frame rate\0"), 24.0);

    /* Print to text */
    if print_preallocated(root) != 0 {
        cJSON_Delete(root);
        exit(1); /* EXIT_FAILURE */
    }
    cJSON_Delete(root);

    /* Our "days of the week" array: */
    root = cJSON_CreateStringArray(strings, 7);

    if print_preallocated(root) != 0 {
        cJSON_Delete(root);
        exit(1);
    }
    cJSON_Delete(root);

    /* Our matrix: */
    root = cJSON_CreateArray();
    i = 0;
    while i < 3 {
        cJSON_AddItemToArray(
            root,
            cJSON_CreateIntArray((*numbers.wrapping_add(i as usize)).as_ptr(), 3),
        );
        i += 1;
    }

    /* cJSON_ReplaceItemInArray(root, 1, cJSON_CreateString("Replacement")); */

    if print_preallocated(root) != 0 {
        cJSON_Delete(root);
        exit(1);
    }
    cJSON_Delete(root);

    /* Our "gallery" item: */
    root = cJSON_CreateObject();
    img = cJSON_CreateObject();
    cJSON_AddItemToObject(root, cs!(b"Image\0"), img);
    cJSON_AddNumberToObject(img, cs!(b"Width\0"), 800.0);
    cJSON_AddNumberToObject(img, cs!(b"Height\0"), 600.0);
    cJSON_AddStringToObject(img, cs!(b"Title\0"), cs!(b"View from 15th Floor\0"));
    thm = cJSON_CreateObject();
    cJSON_AddItemToObject(img, cs!(b"Thumbnail\0"), thm);
    cJSON_AddStringToObject(
        thm,
        cs!(b"Url\0"),
        cs!(b"http:/*www.example.com/image/481989943\0"),
    );
    cJSON_AddNumberToObject(thm, cs!(b"Height\0"), 125.0);
    cJSON_AddStringToObject(thm, cs!(b"Width\0"), cs!(b"100\0"));
    cJSON_AddItemToObject(img, cs!(b"IDs\0"), cJSON_CreateIntArray(ids, 4));

    if print_preallocated(root) != 0 {
        cJSON_Delete(root);
        exit(1);
    }
    cJSON_Delete(root);

    /* Our array of "records": */
    root = cJSON_CreateArray();
    i = 0;
    while i < 2 {
        fld = cJSON_CreateObject();
        cJSON_AddItemToArray(root, fld);
        let f = fields.wrapping_add(i as usize);
        cJSON_AddStringToObject(fld, cs!(b"precision\0"), (*f).precision);
        cJSON_AddNumberToObject(fld, cs!(b"Latitude\0"), (*f).lat);
        cJSON_AddNumberToObject(fld, cs!(b"Longitude\0"), (*f).lon);
        cJSON_AddStringToObject(fld, cs!(b"Address\0"), (*f).address);
        cJSON_AddStringToObject(fld, cs!(b"City\0"), (*f).city);
        cJSON_AddStringToObject(fld, cs!(b"State\0"), (*f).state);
        cJSON_AddStringToObject(fld, cs!(b"Zip\0"), (*f).zip);
        cJSON_AddStringToObject(fld, cs!(b"Country\0"), (*f).country);
        i += 1;
    }

    /* cJSON_ReplaceItemInObject(cJSON_GetArrayItem(root, 1), "City", cJSON_CreateIntArray(ids, 4)); */

    if print_preallocated(root) != 0 {
        cJSON_Delete(root);
        exit(1);
    }
    cJSON_Delete(root);

    root = cJSON_CreateObject();
    let zero_value = ptr::read_volatile(&zero as *const f64);
    cJSON_AddNumberToObject(root, cs!(b"number\0"), 1.0 / zero_value);

    if print_preallocated(root) != 0 {
        cJSON_Delete(root);
        exit(1);
    }
    cJSON_Delete(root);
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn driver(
    strings: *const *const c_char,
    numbers: *const [c_int; 3],
    ids: *const c_int,
    fields: *const record,
) -> c_int {
    /* print the version */
    printf(cs!(b"Version: %s\n\0"), cJSON_Version());

    /* Now some samplecode for building objects concisely: */
    create_objects(strings, numbers, ids, fields);

    0
}
